use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercased host from an http(s) URL. Returns None for anything
/// that does not parse cleanly, so the caller fails closed.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority_end = rest
        .find(|c: char| matches!(c, '/' | '?' | '#'))
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    // Take everything after the last '@' so "allowed.host@evil.example" yields "evil.example".
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    if host_port.starts_with('[') {
        return None; // IPv6 literals are not on the allowlist.
    }
    let host = match host_port.rfind(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Pre-check against the node's own allowlist so an out-of-scope URL
            // is recorded as a failed item rather than trapping the whole run.
            // The host-side handle remains the enforcement point.
            let allowed = host_of(&url).is_some_and(|h| ALLOWED_HOSTS.contains(&h.as_str()));
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
```

I did not implement the `last-input` write. This node's `with` clause grants only `aap:caps/http-client@0.1.0`, and recording to the shared store would require a `state-rw` import, which would widen the node's authority beyond what it was granted. The output is unchanged either way, since that write was the only addition requested.

